{
  "done": false,
  "tool": "manage_backends",
  "args": {
    "backend_id": "backend_001",
    "operation": "refresh",
    "widgets_json": {
      "breach_metric": {
        "description": "Count of open SLA breaches.",
        "endpoint": "/breach-count",
        "gridData": {
          "h": 4,
          "w": 6
        },
        "name": "Open Breaches",
        "type": "metric"
      },
      "sla_newsfeed": {
        "description": "Vendor incident notices feed.",
        "endpoint": "/vendor-notices",
        "gridData": {
          "h": 10,
          "w": 12
        },
        "name": "Vendor Notices",
        "type": "newsfeed"
      },
      "vendor_sla_table": {
        "data": {
          "table": {
            "columnsDefs": [
              {
                "cellDataType": "text",
                "field": "vendor",
                "headerName": "Vendor"
              },
              {
                "cellDataType": "text",
                "field": "status",
                "headerName": "Status",
                "renderFn": "titleCase"
              },
              {
                "cellDataType": "number",
                "field": "latency_ms",
                "headerName": "Latency (ms)"
              },
              {
                "cellDataType": "boolean",
                "field": "breach",
                "headerName": "Breach"
              }
            ]
          }
        },
        "description": "Vendor SLA state with breach flags.",
        "endpoint": "/vendor-sla",
        "gridData": {
          "h": 9,
          "w": 20
        },
        "name": "Vendor SLA Status",
        "params": [
          {
            "label": "Status",
            "options": [
              {
                "label": "Open",
                "value": "Open"
              },
              {
                "label": "Escalated",
                "value": "Escalated"
              },
              {
                "label": "Resolved",
                "value": "Resolved"
              }
            ],
            "paramName": "status",
            "type": "text",
            "value": "Open"
          }
        ],
        "staleTime": 600000
      },
      "sla_runbook": {
        "description": "Runbook for SLA escalations.",
        "endpoint": "/sla-runbook",
        "gridData": {
          "h": 8,
          "w": 12
        },
        "name": "SLA Runbook",
        "type": "markdown"
      }
    }
  }
}
